# -*- coding: utf-8 -*-
T=[]
S="writing2"
T.append(dict(id="g2-op",sec=S,day=1,task="Opinion language and gerunds",before="Clinic · Opinion language and gerunds: choose",
 emoji="🎤",kicker="TAKE A STAND",title="Say What You Think,<br>Say It Right",ch1="The stage",
 hook="Welcome to the debate stage. In an Academic Discussion post, your first sentence must show your position. But a small grammar slip can ruin a strong opinion. Today you will learn the phrases that make your stand clear.",
 A="I am in favor of <b>work</b> from home.",B="I am in favor of <b>working</b> from home.",
 cmp="Look at these two openings. Version A: I am in favor of work from home. Version B: I am in favor of working from home. Both state a position, but only one is built correctly.",
 verdict="Version B is correct. After a preposition like of, English uses the -ing form. Version A uses the base form, which sounds like a mistake, even though the opinion is clear.",
 stampA="SHAKY STAND",whyHead="Your first sentence matters",whySub="Raters read your position first",why="Why does this matter? The first sentence tells the rater your position. If it is clear and accurate, the rest of your post starts with a strong impression.",
 rule=[
  dict(legend=["s:position phrase","v:-ing form"],sub="After a preposition: -ing",rows=["s:I am in favor of|v:working|n:from home"],say="After a preposition, use the -ing form. I am in favor of working from home. She is against raising fees. They are interested in studying abroad. The verb after of, against and in always ends in ing."),
  dict(sub="Agree and disagree are verbs",pair=["✗","I <b>am agree</b> with Ana.","✓","I <b>agree</b> with Ana."],say="Agree and disagree are verbs, not adjectives. I agree with Ana. I disagree with the author. We never say I am agree."),
  dict(sub="Strong, medium and soft opinions",rows=["v:I strongly believe|q:I tend to think|n:It seems to me"],note="Match the strength to your evidence",say="You can vary the strength of an opinion. I strongly believe. I tend to think. It seems to me. Strong phrases need strong reasons. Softer ones are safer when you have less evidence."),
  dict(sub="Position + classmate",rows=["n:I side with Ana,|q:but for a different reason"],note="side with · differ from · build on",say="You can also show your position by relating to a classmate. I side with Ana, but for a different reason. I would build on Ben's point. These phrases show the rater that you read the other posts."),
  dict(sub="Which preposition?",rows=["v:agree with|q:disagree with|n:in favor of|n:against"],note="side with · interested in · opposed to",say="Learn these pairs as chunks. Agree with a person, in favor of an idea, against a plan, opposed to a policy. After each of these prepositions, you will use a noun or an ing verb.")],
 trap=dict(es="Estoy <b>a favor de</b> trabajar en casa. · <b>Estoy de acuerdo</b>.",esnote="infinitive after a preposition · estar + de acuerdo",say1="Now the trap. In Spanish, you say estoy a favor de trabajar, with an infinitive after the preposition. And you say estoy de acuerdo, with the verb estar.",
  es2="estoy a favor de <b>trabajar</b>",enbad="I am in favor of <b>to work</b>",say2="So Spanish speakers write: I am in favor of to work from home. Or: I am agree with Ana. Both copy the Spanish structure into English.",
  stop="Preposition + ing. Agree is a verb.",engood="I am in favor of <b>working</b>. I <b>agree</b> with Ana.",say3="So, stop. After a preposition, put the verb in the ing form. And remove am from agree. Two small changes, and your position sounds natural.",
  more=[["Trap 2 · disagree that ✗","I disagree <b>with that</b> online classes are cheaper.","Fixed ✓","I disagree <b>that</b> online classes are cheaper.","🔧","The second trap is disagree with that. Say I disagree that, or I disagree with the idea that. Not with that alone."]]),
 quiz=["She is against ___ the fee.",["raise","raising","to raise"],1],
 quizsay="Quick quiz. She is against, blank, the fee. After the preposition against, which form? ... The answer is B. Raising. Preposition plus ing.",
 fix=dict(sub="Fix the opening",row="s:I|g:am|v:agree|n:with Ana",say="Fix this one. I am agree with Ana. Remove am. Agree is a verb: I agree with Ana."),
 recap=["<b>Preposition + -ing</b>: in favor of working","<b>I agree / I disagree</b>: no am","Match the <b>strength</b> of your opinion to your evidence"],
 recapsay="Three things to remember. One, after a preposition use the ing form. Two, agree and disagree are verbs, with no am. Three, match the strength of your opinion to your evidence.",
 done="Strong stand!",donesay="Strong stand! Your position is clear and correct. Go to the practice and write that first sentence with confidence. Good luck!",
 check=dict(why1="After a preposition, use the -ing form.",q2="Choose the correct sentence.",a2="I agree with her.",w2=["I am agree with her.","I am agreeing with her.","I agree to her."],why2="Agree is a verb.")))
T.append(dict(id="g2-pr",sec=S,day=2,task="Present simple and present continuous in claims",before="Clinic · Present simple and present continuous in claims: choose",
 emoji="📈",kicker="HABIT OR TREND?",title="Always True<br>or Changing Now?",ch1="Two clocks",
 hook="Welcome, analyst. Today you will learn to choose between two present tenses. One describes what is always true. The other describes what is changing right now. Choose well, and your claims sound precise.",
 A="Many students <b>are using</b> phones in class every day.",B="Many students <b>use</b> phones in class every day.",
 cmp="Look at these two sentences. Version A: many students are using phones in class every day. Version B: many students use phones in class every day. They look almost identical, but one of them fits the sentence better.",
 verdict="Version B fits. Every day shows a habit, and habits use the present simple. Version A uses the continuous, which describes something temporary or changing, so it does not match every day.",
 stampA="WRONG CLOCK",whyHead="Claims need accurate tenses",whySub="General facts · trends · opinions",why="Why does this matter? In a discussion post, you state facts, habits and trends all the time. The right tense tells the reader if you mean always, or right now.",
 rule=[
  dict(legend=["s:always true","v:changing now"],sub="Two clocks",rows=["s:present simple|v:present continuous"],say="Think of two clocks. The present simple is for things that are always true, habits and facts. The present continuous is for things that are happening now, or changing now."),
  dict(sub="Present simple: habits and facts",rows=["s:Students|v:use|n:phones|q:every day"],note="always · usually · every day · in general",say="Use the present simple for habits and general facts. Students use phones every day. Research suggests that sleep improves memory. Words like always, usually and every day tell you to choose it."),
  dict(sub="Present continuous: trends",rows=["s:More people|aux:are|v:working|n:from home|q:these days"],note="now · these days · increasingly · more and more",say="Use the continuous for trends and changes. More people are working from home these days. Prices are rising. Words like now, these days and increasingly warn you that something is changing."),
  dict(sub="Verbs you do not use in the continuous",pair=["✗","I <b>am knowing</b> the answer.","✓","I <b>know</b> the answer."],note="know · believe · want · need · prefer · seem",say="Some verbs describe states, not actions, so they never take the continuous. Know, believe, want, need, prefer and seem. I know the answer. I believe it is unfair. Never I am knowing."),
  dict(sub="Opinion verbs",rows=["s:I|v:think|n:that|s:it is unfair"],note="I think · I believe · I feel → simple",say="Opinion verbs follow the same rule. I think that it is unfair. I believe the plan is costly. Keep them in the present simple.")],
 trap=dict(es="Estoy <b>pensando</b> que es injusto. · Estoy <b>queriendo</b>…",esnote="Spanish uses the gerund freely",say1="Now the trap. Spanish uses the gerund very freely: estoy pensando que es injusto. It is common in conversation, and it sounds natural.",
  es2="estoy <b>pensando</b> que es injusto",enbad="I <b>am thinking</b> that it is unfair",say2="So Spanish speakers write: I am thinking that it is unfair. Or: I am wanting a change. In English, an opinion or a state needs the simple form.",
  stop="Opinion or state? Use the simple form.",engood="I <b>think</b> that it is unfair. I <b>want</b> a change.",say3="So, stop. If you are stating an opinion or a state, like think, know, want or need, use the present simple. Use the continuous only for changing actions.",
  more=[["Trap 2 · the trend ✗","Right now prices <b>rise</b> quickly.","Fixed ✓","Right now prices <b>are rising</b> quickly.","📈","The second trap is the trend. Right now and these days announce a change in progress. Use the continuous: prices are rising quickly."]]),
 quiz=["Many students ___ phones in class every day.",["are using","use","is using"],1],
 quizsay="Quick quiz. Many students, blank, phones in class every day. Every day means a habit. ... The answer is B. Use. A habit needs the present simple.",
 fix=dict(sub="Fix the sentence",row="s:I|g:am|g:knowing|v:know|n:the answer",say="Fix this one. I am knowing the answer. Know is a state verb. Remove am and ing: I know the answer."),
 recap=["<b>Present simple</b>: habits, facts, opinions","<b>Present continuous</b>: trends and changes now","<b>State verbs</b> (know, want, believe): never continuous"],
 recapsay="Three things to remember. One, the present simple for habits, facts and opinions. Two, the continuous for trends and changes now. Three, state verbs like know, want and believe are never continuous.",
 done="Two clocks, one analyst!",donesay="Two clocks, one analyst! You can now choose the right present tense for every claim. Go to the practice. Good luck!",
 check=dict(why1="A habit needs the present simple.",q2="Choose the correct sentence.",a2="I know the answer.",w2=["I am knowing the answer.","I am know the answer.","I knowing the answer."],why2="Know is a state verb.")))
T.append(dict(id="g2-ex",sec=S,day=3,task="Tenses for examples",before="Clinic · Tenses for examples: past simple and present perfect: choose",
 emoji="🧳",kicker="THE EXAMPLE TRAVELER",title="Past or Present Perfect<br>in Your Examples",ch1="Pack your example",
 hook="Welcome, traveler. A good discussion post needs a concrete example, and examples usually come from the past. But which past tense should you pack? Today you will choose the right one every time.",
 A="Last year my city <b>has built</b> a new park.",B="Last year my city <b>built</b> a new park.",
 cmp="Look at these two sentences. Version A: last year my city has built a new park. Version B: last year my city built a new park. One of them carries a tense that does not belong with last year.",
 verdict="Version B is correct. Last year is a finished time, so the past simple fits. Version A uses the present perfect, which connects to now, and clashes with a finished time.",
 stampA="WRONG TICKET",whyHead="Examples make your argument real",whySub="Specific examples need exact tenses",why="Why does this matter? Raters reward concrete examples. But an example with the wrong tense confuses the timeline, and weakens the point you are trying to make.",
 rule=[
  dict(legend=["s:finished","v:connected to now"],sub="Two bags",rows=["s:past simple|v:present perfect"],say="You have two bags. The past simple bag is for finished events. The present perfect bag is for events connected to the present. Choose the bag by the time word."),
  dict(sub="Finished time → past simple",rows=["q:Last year|s:the city|v:built|n:a park"],note="yesterday · last year · in 2019 · when I was young",say="With a finished time, use the past simple. Last year the city built a park. In 2019 I visited Sucre. When I was young, my school opened a library."),
  dict(sub="Connected to now → present perfect",rows=["q:Since 2020|s:prices|aux:have|v:risen|n:sharply"],note="since · for · so far · recently · never",say="With since, for, so far or recently, use the present perfect. Since 2020 prices have risen sharply. Scientists have studied this issue for decades."),
  dict(sub="For examples: start with the present perfect, continue with the past",rows=["n:Cities have invested in parks.","n:In 2018,|v:Cochabamba|n:opened three."],note="Result now → details in the past simple",say="Here is a pro tip. Start with the present perfect to state the result, then switch to the past simple for details. Cities have invested in parks. In 2018, Cochabamba opened three. The switch tells a clear story."),
  dict(sub="Trend words",pair=["Use present perfect","<b>so far</b> · <b>recently</b> · <b>lately</b>","Use past simple","<b>in 2018</b> · <b>last month</b> · <b>ago</b>"],say="Remember these signal words. So far, recently and lately belong with the present perfect. In 2018, last month and two years ago belong with the past simple.")],
 trap=dict(es="<b>He visitado</b> Sucre en 2019.",esnote="Spanish can use the perfect with finished times",say1="Now the trap. Spanish often uses the present perfect for events that feel close or recent: he visitado Sucre en 2019. That can be natural in Spanish conversation.",
  es2="<b>he visitado</b> Sucre en 2019",enbad="I <b>have visited</b> Sucre in 2019",say2="So Spanish speakers write: I have visited Sucre in 2019. In English, a specific past date needs the past simple. The present perfect cannot take a finished time.",
  stop="A date? Past simple.",engood="I <b>visited</b> Sucre in 2019.",say3="So, stop. If your sentence has a specific past date or time, change to the past simple. If it has since or for, use the present perfect.",
  more=[["Trap 2 · since + past ✗","Since 2020 prices <b>rose</b> sharply.","Fixed ✓","Since 2020 prices <b>have risen</b> sharply.","⏳","The second trap is since with the past simple. Since reaches the present, so use the present perfect: prices have risen."]]),
 quiz=["Last year my city ___ a new park.",["has built","built","builds"],1],
 quizsay="Quick quiz. Last year my city, blank, a new park. Last year is finished. ... The answer is B. Built. Past simple.",
 fix=dict(sub="Fix the sentence",row="n:I|g:have visited|v:visited|n:Sucre|q:in 2019",say="Fix this one. I have visited Sucre in 2019. A date needs the past simple. I visited Sucre in 2019."),
 recap=["<b>Finished time</b> → past simple","<b>Since / for / so far</b> → present perfect","<b>Result now</b>, then <b>details in the past</b>"],
 recapsay="Three things to remember. One, a finished time needs the past simple. Two, since, for and so far need the present perfect. Three, state the result now, then give the details in the past.",
 done="Examples packed!",donesay="Examples packed, traveler! Your timeline will always be clear. Go to the practice. Good luck!",
 check=dict(why1="Last year is a finished time.",q2="Choose the correct sentence.",a2="Since 2020 prices have risen sharply.",w2=["Since 2020 prices rose sharply.","Since 2020 prices rise sharply.","Since 2020 prices were rising sharply."],why2="Since needs the present perfect.")))
T.append(dict(id="g2-lk",sec=S,day=4,task="Linkers and comma splices",before="Clinic · Linkers, punctuation and comma splices: choose",
 emoji="🚥",kicker="THE LINKER TRAFFIC LIGHTS",title="Green, Yellow,<br>Red Linkers",ch1="Traffic lights",
 hook="Welcome to the linker traffic lights. Words like however, therefore and because tell the reader which way your ideas are going. But use them with the wrong punctuation, and you cause a crash.",
 A="The plan is cheap<b>, however</b> it is slow.",B="The plan is cheap<b>; however,</b> it is slow.",
 cmp="Look at these two sentences. Version A: the plan is cheap, however it is slow. Version B: the plan is cheap; however, it is slow. Same idea, different punctuation. One of them runs the red light.",
 verdict="Version A runs the red light. A comma cannot join two sentences before however. Version B uses a semicolon before however, and a comma after it, and the traffic flows.",
 stampA="RED LIGHT",whyHead="Linkers show logic, punctuation shows control",whySub="Discussion posts depend on clear connections",why="Why does this matter? Linkers show the logic of your argument. When they are punctuated correctly, your ideas connect smoothly. When they are not, readers notice the error first.",
 rule=[
  dict(legend=["s:+ addition","v:contrast","q:reason / result"],sub="Three light colors",rows=["s:moreover|v:however|q:therefore"],say="Linkers have three jobs. Green lights add ideas: moreover, in addition. Yellow lights show contrast: however, although. Red lights show results: therefore, as a result."),
  dict(sub="Sentence linkers: ; however,",rows=["s:Fees are high|v:;|q:however,|s:students pay"],note="; however, · ; therefore, · ; moreover,",say="Sentence linkers like however and therefore connect two complete sentences. Put a semicolon, or a full stop, before them, and a comma after. Fees are high; however, students pay."),
  dict(sub="Conjunctions: , but · , so",rows=["s:It was late|v:, so|s:we left"],note="comma + and · but · so · or",say="Conjunctions like and, but and so are different. Use a comma before them. It was late, so we left. The plan is cheap, but it is slow. No semicolon here."),
  dict(sub="Although and but do not travel together",pair=["✗","<b>Although</b> it is costly, <b>but</b> it is useful.","✓","<b>Although</b> it is costly, it is useful."],say="Never use although and but together. Choose one. Although it is costly, it is useful. Or: it is costly, but it is useful. Using both is a double signal."),
  dict(sub="Quality over quantity",rows=["q:Two or three linkers in a post"],note="Too many linkers sound mechanical",say="Finally, do not use too many linkers. Two or three in a short post is enough. If every sentence starts with moreover or furthermore, the post sounds robotic.")],
 trap=dict(es="Es barato<b>,</b> <b>sin embargo</b> es lento. · <b>Aunque</b> es caro<b>, pero</b>…",esnote="Spanish allows commas and aunque … pero",say1="Now the trap. In Spanish, commas before sin embargo are common: es barato, sin embargo es lento. And you can say aunque es caro, pero es útil, in the same sentence.",
  es2="es barato<b>,</b> sin embargo es lento",enbad="it is cheap<b>,</b> however it is slow",say2="So Spanish speakers copy those patterns: it is cheap, however it is slow. Or: although it is costly, but it is useful. English does not accept either one.",
  stop="Semicolon before however. Although OR but.",engood="It is cheap<b>; however,</b> it is slow.",say3="So, stop. Check every linker. If it is however or therefore, add a semicolon before and a comma after. And never put although and but together.",
  more=[["Trap 2 · comma splice ✗","She studied hard<b>,</b> she passed the exam.","Fixed ✓","She studied hard<b>, so</b> she passed the exam.","🔗","The second trap is the comma splice. Two sentences cannot be joined by a comma alone. Add so, or use a semicolon or a full stop."]]),
 quiz=["The plan is cheap; ___ it is slow.",["however","however,","but"],1],
 quizsay="Quick quiz. The plan is cheap, semicolon, blank, it is slow. Which linker is punctuated correctly? ... The answer is B. However, with a comma after it.",
 fix=dict(sub="Fix the sentence",row="n:Although it is costly,|g:but|s:it is useful",say="Fix this one. Although it is costly, but it is useful. Delete but. Although it is costly, it is useful."),
 recap=["<b>; however,</b> · <b>; therefore,</b> (semicolon + comma)","<b>, but · , so · , and</b> (comma + conjunction)","<b>Although OR but</b>, never both"],
 recapsay="Three things to remember. One, semicolon before however, and a comma after. Two, comma plus but, so or and. Three, although or but, never both.",
 done="Green light!",donesay="Green light! Your linkers are punctuated like a pro. Go to the practice. Remember: semicolon before however. Good luck!",
 check=dict(why1="However needs a semicolon before it and a comma after.",q2="Choose the correct sentence.",a2="Although it is costly, it is useful.",w2=["Although it is costly, but it is useful.","Although it is costly but it is useful.","It is costly although, but useful."],why2="Although and but do not go together.")))
